:PROCEDURE SumRows;
	:PARAMETERS aRows;
	:DECLARE i, nTotal, bDone;

	nTotal := 0;
	bDone := .F.;

	:FOR i := 1 :TO ALen(aRows);
		:TRY;
			nTotal += aRows[i];
		:FINALLY;
			bDone := nTotal > 100;
