:PROCEDURE CloseOrder;
	:PARAMETERS sOrdNo;
	:DECLARE bDone, oErr;

	bDone := .F.;

	:TRY;
		bDone := RunSQL("UPDATE ordtask SET status = 'Done' WHERE ordno = ?",, {sOrdNo});
	:CATCH;
		oErr := GetLastSSLError();
		ErrorMes("[ERROR] CloseOrder " + sOrdNo, Left(oErr:Description, 2000));
		ClearLastSSLError();
	:ENDTRY;

	:RETURN bDone;
:ENDPROC;

